90	     * Whether this owner was one of a bulk signup for its registration day (more than
91	     * 80 owners created for that day). Derived at response time, never persisted.
92	     */
93	    @Transient
94	    private Boolean bulkSignupWarning;
95	
96	    /**
97	     * Whether this owner's city is approaching the per-city capacity limit — the city
98	     * already holds between 40 and 49 owners (the hard limit being 50). Derived at
99	     * response time from the persisted city, never persisted.
100	     */
101	    @Transient
102	    private Boolean capacityWarning;
103	
104	    /**
105	     * The number of owners sharing this owner's household (the same householdId),
106	     * counting this owner. Derived at response time from the persisted householdId,
107	     * never persisted. Drives the 'GOLD' membership tier (3 or more members).
108	     */
109	    @Transient
110	    private Integer householdSize;
111	
112	    /**
113	     * Whether this owner is a soft-match of an existing (other) owner — sharing that
114	     * owner's lastName and postcode but carrying a different telephone (so it is not a
115	     * hard duplicate). Derived at response time, never persisted.
116	     */
117	    @Transient
118	    private Boolean possibleDuplicate;
119	
120	    /**
121	     * The id of the existing owner this owner soft-matches (see {@link #possibleDuplicate}),
122	     * or null when it soft-matches none. Derived at response time, never persisted.
123	     */
124	    @Transient
125	    private Integer possibleDuplicateOf;
126	
127	    /**
128	     * The owner's membership level, capped so it never exceeds one above the current
129	     * maximum level among the other members of its household. Derived at response time
130	     * from the persisted fields plus the household, never persisted. When null (e.g. for
131	     * list responses that skip the assignment step) the level falls back to the uncapped
132	     * value computed directly from the owner's fields.
133	     */
134	    @Transient
135	    private Integer membershipLevel;
136	
137	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
