281	        this.possibleDuplicate = possibleDuplicate;
282	    }
283	
284	    public Integer getPossibleDuplicateOf() {
285	        return this.possibleDuplicateOf;
286	    }
287	
288	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
289	        this.possibleDuplicateOf = possibleDuplicateOf;
290	    }
291	
292	    public Integer getMembershipLevel() {
293	        return this.membershipLevel;
294	    }
295	
296	    public void setMembershipLevel(Integer membershipLevel) {
297	        this.membershipLevel = membershipLevel;
298	    }
299	
300	    protected Set<Pet> getPetsInternal() {
301	        if (this.pets == null) {
302	            this.pets = new HashSet<>();
303	        }
304	        return this.pets;
305	    }
306	
307	    protected void setPetsInternal(Set<Pet> pets) {
308	        this.pets = pets;
309	    }
310	
311	    public List<Pet> getPets() {
312	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
313	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
314	        return Collections.unmodifiableList(sortedPets);
315	    }
316	
317	    public void setPets(List<Pet> pets) {
318	        this.pets = new HashSet<>(pets);
319	    }
320	
321	    public void addPet(Pet pet) {
322	        getPetsInternal().add(pet);
323	        pet.setOwner(this);
324	    }
325	
326	    /**
327	     * Return the Pet with the given name, or null if none found for this Owner.
328	     *
329	     * @param name to test
330	     * @return true if pet name is already in use
331	     */
332	    public Pet getPet(String name) {
333	        return getPet(name, false);
334	    }
335	
336	    /**
337	     * Return the Pet with the given name, or null if none found for this Owner.
338	     *
339	     * @param name to test
340	     * @return true if pet name is already in use
341	     */
342	    public Pet getPet(String name, boolean ignoreNew) {
343	        name = name.toLowerCase();
344	        for (Pet pet : getPetsInternal()) {
345	            if (!ignoreNew || !pet.isNew()) {
346	                String compName = pet.getName();
347	                compName = compName.toLowerCase();
348	                if (compName.equals(name)) {
349	                    return pet;
350	                }
351	            }
352	        }
353	        return null;
354	    }
355	
356	    public Pet getPet(Integer petId) {
357	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
358	    }
359	
360	    @Override
361	    public String toString() {
362	        return new ToStringCreator(this)
363	
364	            .append("id", this.getId())
365	            .append("new", this.isNew())
366	            .append("lastName", this.getLastName())
367	            .append("firstName", this.getFirstName())
368	            .append("address", this.address)
369	            .append("city", this.city)
370	            .append("telephone", this.telephone)
371	            .toString();
372	    }
373	}
