1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.function.common.MembershipLevels;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Records the owner's membership level as the transient {@code membershipLevel}, capping it so
13	 * it never exceeds one above the current maximum level among the <em>other</em> members of its
14	 * household (owners sharing the same {@code householdId}, this owner excluded). With no other
15	 * household member no cap applies and the uncapped level stands.
16	 *
17	 * <p>Runs after {@link AssignOwnerHouseholdSize} — the level depends on the household size — on
18	 * both the create pipeline (after Save, so the new owner has an id and is excluded by it) and
19	 * the read pipeline, so the capped level is identical whether returned from the create response
20	 * or a later GET, mirroring {@link AssignOwnerHouseholdSize} and {@link AssignOwnerPossibleDuplicate}.
21	 */
22	public class AssignOwnerMembershipLevel {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String householdId = owner.getHouseholdId();
26	        if (householdId == null || householdId.isBlank()) {
27	            owner.setMembershipLevel(MembershipLevels.of(owner));
28	            return;
29	        }
30	        Integer householdSize = owner.getHouseholdSize();
31	        List<Owner> others = new ArrayList<>();
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (existing.getId() == null
34	                    || (owner.getId() != null && existing.getId().equals(owner.getId()))) {
35	                continue;
36	            }
37	            if (!householdId.equals(existing.getHouseholdId())) {
38	                continue;
39	            }
40	            // All members of a household share the same size; align it so each member's level
41	            // is computed on the same basis a GET would report for that member.
42	            existing.setHouseholdSize(householdSize);
43	            others.add(existing);
44	        }
45	        owner.setMembershipLevel(MembershipLevels.capped(owner, others));
46	    }
47	}
