1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.util.Map;
4	
5	/**
6	 * Fixed lookups used to derive an owner's locality. The locality prefers the postcode
7	 * range and falls back to the city-to-region table; cities not in the table (and with no
8	 * postcode-derived region) derive the locality {@link #UNKNOWN}.
9	 */
10	public final class Localities {
11	
12	    /** The canonical region string returned for any city not in {@link #CITY_REGION}. */
13	    public static final String UNKNOWN = "UNKNOWN";
14	
15	    /** City -> canonical region. */
16	    private static final Map<String, String> CITY_REGION = Map.of(
17	            "Sydney", "NSW",
18	            "Melbourne", "VIC",
19	            "Brisbane", "QLD");
20	
21	    /** Region -> inclusive 4-digit postcode range {@code {low, high}}. */
22	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
23	            "NSW", new int[] {2000, 2099},
24	            "VIC", new int[] {3000, 3099},
25	            "QLD", new int[] {4000, 4099});
26	
27	    /** Region -> IANA timezone name. */
28	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
29	            "NSW", "Australia/Sydney",
30	            "VIC", "Australia/Melbourne",
31	            "QLD", "Australia/Brisbane");
32	
33	    private Localities() {
34	    }
35	
36	    /**
37	     * Derive the canonical region for a city, or {@link #UNKNOWN} when the city is not
38	     * in the fixed table (including when {@code city} is null).
39	     */
40	    public static String region(String city) {
41	        return CITY_REGION.getOrDefault(city, UNKNOWN);
42	    }
43	
44	    /**
45	     * Derive the canonical region, preferring the postcode. When {@code postcode} is a
46	     * 4-digit value falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
47	     * QLD 4000-4099) that region is returned, disambiguating cities that share a name.
48	     * Otherwise (postcode absent, non-numeric, or in no known range) the fixed
49	     * city-to-region table is used, returning {@link #UNKNOWN} for an unknown city.
50	     */
51	    public static String locality(String city, String postcode) {
52	        String byPostcode = regionForPostcode(postcode);
53	        return byPostcode != null ? byPostcode : region(city);
54	    }
55	
56	    /**
57	     * The region whose range contains the given 4-digit postcode, or {@code null} when
58	     * the postcode is absent, non-numeric, or in no known range.
59	     */
60	    private static String regionForPostcode(String postcode) {
61	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
62	            return null;
63	        }
64	        int value = Integer.parseInt(postcode);
65	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
66	            int[] range = entry.getValue();
67	            if (value >= range[0] && value <= range[1]) {
68	                return entry.getKey();
69	            }
70	        }
71	        return null;
72	    }
73	
74	    /**
75	     * The locality of a stored owner: the {@code REGION} component of its customerCode
76	     * (everything before the first {@code '-'} of the {@code <REGION>-<HASH8>} identity),
77	     * so the locality now follows from the same region-and-hash identity the customerCode
78	     * carries. Falls back to {@link #locality(String, String)} when the customerCode is
79	     * absent or carries no region prefix (e.g. legacy records).
80	     */
81	    public static String localityOf(String customerCode, String city, String postcode) {
82	        if (customerCode != null) {
83	            int dash = customerCode.indexOf('-');
84	            if (dash > 0) {
85	                return customerCode.substring(0, dash);
86	            }
87	        }
88	        return locality(city, postcode);
89	    }
90	
91	    /**
92	     * The IANA timezone name for an owner's locality, derived from the same customerCode
93	     * region prefix (falling back to city/postcode) that {@link #localityOf(String, String,
94	     * String)} yields, via the fixed region-to-timezone table (NSW-&gt;Australia/Sydney,
95	     * VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane). Returns {@code null} when the
96	     * locality has no mapped timezone (i.e. {@link #UNKNOWN}).
97	     */
98	    public static String timezoneOf(String customerCode, String city, String postcode) {
99	        return REGION_TIMEZONE.get(localityOf(customerCode, city, postcode));
100	    }
101	
102	    /**
103	     * The inclusive {@code {low, high}} 4-digit postcode range for a region, or {@code null}
104	     * when the region is not in the fixed table (i.e. {@link #UNKNOWN}), meaning any 4-digit
105	     * postcode is acceptable.
106	     */
107	    public static int[] postcodeRange(String region) {
108	        return REGION_POSTCODES.get(region);
109	    }
110	}
