1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.time.LocalDate;
4	import java.util.Collection;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Derives an owner's membership standing from stable owner fields as a points score and
10	 * the numeric level (1 to 4) that score maps to, replacing the former rules that computed
11	 * the level directly.
12	 *
13	 * <p>Points start at 0 and accrue independently: {@link #POINTS_EMAIL} (2) when the owner
14	 * has an email, {@link #POINTS_NO_NAMESAKE} (1) when the owner's {@code namesakeCount} is
15	 * 0, {@link #POINTS_HOUSEHOLD} (2) when the owner belongs to a household of three or more
16	 * members ({@code householdSize} of 3 or more), and {@link #POINTS_TENURE} (3) for a
17	 * tenure of more than {@link #TENURE_FISCAL_YEARS_FOR_POINTS} elapsed fiscal years,
18	 * counted as the difference between the fiscal year of the registration date and the
19	 * current fiscal year (see {@link FiscalYear}).
20	 *
21	 * <p>The points map to a level: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points and
22	 * 4 for 6 or more points.
23	 */
24	public final class MembershipLevels {
25	
26	    /** Points gained when the owner has an email. */
27	    public static final int POINTS_EMAIL = 2;
28	
29	    /** Points gained when the owner's {@code namesakeCount} is 0. */
30	    public static final int POINTS_NO_NAMESAKE = 1;
31	
32	    /** Points gained for a household of three or more members. */
33	    public static final int POINTS_HOUSEHOLD = 2;
34	
35	    /** Points gained for a tenure of more than {@link #TENURE_FISCAL_YEARS_FOR_POINTS}
36	     *  elapsed fiscal years. */
37	    public static final int POINTS_TENURE = 3;
38	
39	    /** Tenure points require strictly more than this many elapsed fiscal years of tenure. */
40	    public static final int TENURE_FISCAL_YEARS_FOR_POINTS = 1;
41	
42	    private MembershipLevels() {
43	    }
44	
45	    /**
46	     * Compute the membership points for the given owner.
47	     */
48	    public static int points(Owner owner) {
49	        int points = 0;
50	        String email = owner.getEmail();
51	        if (email != null && !email.isBlank()) {
52	            points += POINTS_EMAIL;
53	        }
54	        Integer namesakeCount = owner.getNamesakeCount();
55	        if (namesakeCount != null && namesakeCount == 0) {
56	            points += POINTS_NO_NAMESAKE;
57	        }
58	        Integer householdSize = owner.getHouseholdSize();
59	        if (householdSize != null && householdSize >= 3) {
60	            points += POINTS_HOUSEHOLD;
61	        }
62	        if (hasTenurePoints(owner)) {
63	            points += POINTS_TENURE;
64	        }
65	        return points;
66	    }
67	
68	    /**
69	     * Compute the membership level for the given owner from its points.
70	     */
71	    public static int of(Owner owner) {
72	        int points = points(owner);
73	        if (points <= 1) {
74	            return 1;
75	        }
76	        if (points <= 3) {
77	            return 2;
78	        }
79	        if (points <= 5) {
80	            return 3;
81	        }
82	        return 4;
83	    }
84	
85	    /**
86	     * Compute the membership level for the given owner, capped so it never exceeds one above
87	     * the highest level among the other members of its household. The {@code householdMembers}
88	     * are the owner's fellow household members (this owner excluded); when there are none the
89	     * uncapped level from {@link #of(Owner)} is returned unchanged.
90	     */
91	    public static int capped(Owner owner, Collection<Owner> householdMembers) {
92	        int base = of(owner);
93	        int ceiling = Integer.MIN_VALUE;
94	        for (Owner member : householdMembers) {
95	            ceiling = Math.max(ceiling, of(member));
96	        }
97	        if (ceiling == Integer.MIN_VALUE) {
98	            return base;
99	        }
100	        return Math.min(base, ceiling + 1);
101	    }
102	
103	    private static boolean hasTenurePoints(Owner owner) {
104	        LocalDate registrationDate = owner.getRegistrationDate();
105	        if (registrationDate == null) {
106	            return false;
107	        }
108	        int elapsedFiscalYears = FiscalYear.of(LocalDate.now()) - FiscalYear.of(registrationDate);
109	        return elapsedFiscalYears > TENURE_FISCAL_YEARS_FOR_POINTS;
110	    }
111	}
