1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the size of the owner's household — the number of owners sharing the same
9	 * {@code householdId}, counting this owner — as the transient {@code householdSize}.
10	 * Drives the 'GOLD' membership tier (a household of 3 or more members).
11	 *
12	 * <p>An owner with no household ({@code householdId} null or blank) has a household of
13	 * one. Runs on both the create pipeline (after Save, so the new owner is counted) and
14	 * the read pipeline, so the size — and therefore the tier — is identical whether returned
15	 * from the create response or a later GET, mirroring {@link AssignOwnerBulkSignupWarning}.
16	 */
17	public class AssignOwnerHouseholdSize {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = owner.getHouseholdId();
21	        if (householdId == null || householdId.isBlank()) {
22	            owner.setHouseholdSize(1);
23	            return;
24	        }
25	        long count = ownerRepository.findAll().stream()
