3	import java.util.HashSet;
4	import java.util.Set;
5	import java.util.stream.Collectors;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.function.common.Localities;
11	import org.springframework.samples.petclinic.rest.function.common.Sha256;
12	
13	/**
14	 * Assigns the {@code customerCode} to a newly built owner, formatted
15	 * {@code <REGION>-<HASH8>} where {@code REGION} is the region code derived from the
16	 * owner's postcode (see {@link Localities#locality(String, String)}) and {@code HASH8}
17	 * is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
18	 * normalized telephone (E.164, see {@link OwnerTelephone}) concatenated with its last
19	 * name (e.g. {@code NSW-1A2B3C4D}).
20	 *
21	 * <p>This is a stable identity: the region-and-hash value carries no sequence number, so
22	 * it does not depend on how many owners already exist. When that value collides with an
23	 * existing owner's {@code customerCode}, {@code -<n>} is appended with the smallest
24	 * {@code n} of 2 or more that makes it unique, so distinct owners always get distinct
25	 * customerCodes. Every value built from the customerCode — the
26	 * membershipNumber and its checkDigit, the create audit line and the derived locality —
27	 * follows from this region-and-hash identity. Mutates the owner in place (the same object
28	 * {@link SaveOwner} persists).
29	 */
30	public class AssignOwnerCustomerCode {
31	
32	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
33	        String region = Localities.locality(owner.getCity(), owner.getPostcode());
34	        String telephone = OwnerTelephone.canonical(owner.getTelephone());
35	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
36	        String base = region + "-" + Sha256.hexPrefix(telephone + lastName, 8);
37	
38	        Set<String> taken = ownerRepository.findAll().stream()
39	                .filter(existing -> existing.getId() == null
40	                        || !existing.getId().equals(owner.getId()))
41	                .map(Owner::getCustomerCode)
42	                .filter(code -> code != null)
43	                .collect(Collectors.toCollection(HashSet::new));
44	
45	        String customerCode = base;
46	        for (int n = 2; taken.contains(customerCode); n++) {
47	            customerCode = base + "-" + n;
48	        }
49	        owner.setCustomerCode(customerCode);
50	    }
51	}
